import { password as passwordInput } from '@inquirer/prompts'
import type { ArgumentsCamelCase, Argv } from 'yargs'
import { withTelemetryEvent } from '../../telemetry'
import { input, select } from '@inquirer/prompts'
import {
    type CredentialPreview,
    type Creds,
    fetchCredentials,
    removeCredentials,
    storeCredentials,
    updateDefaultCredential,
} from '../../auth'
import { logger } from '../../logger'
import chalk from 'chalk'
import { getOAuthTokens } from '../../auth/OAuth'
import { getUISessionToken } from '../../auth/basic-auth'

type Options = {
    add: string | undefined
    delete: string | undefined
    use: string | undefined
    list: boolean | undefined
    type: string | undefined
    alias: string | undefined
    username: string | undefined
    passwordStdin: boolean | undefined
}

type AddArguments = {
    host: string
    type: string | undefined
    alias: string | undefined
    username: string | undefined
    passwordStdin: boolean | undefined
}

export type AuthInfo = {
    host: string
    alias: string
} & (
    | { type: 'oauth' }
    | {
          type: 'basic'
          username: string
          password: string
      }
)

export function builder(yargs: Argv) {
    return yargs
        .option('delete', {
            describe: 'Alias of authentication credential to delete',
            type: 'string',
        })
        .option('use', {
            describe: 'Alias of authentication credential to use by default',
            type: 'string',
        })
        .option('list', {
            describe: 'List all available authentication credentials',
            type: 'boolean',
        })
        .option('add', {
            describe: 'Instance name or url to store authentication credentials for',
            type: 'string',
        })
        .option('type', {
            describe: 'Type of authentication to use for new authentication credential',
            type: 'string',
            choices: ['basic', 'oauth'],
            defaultValue: 'basic',
        })
        .option('alias', {
            describe: 'The alias to use for new authentication credential',
            type: 'string',
        })
        .option('username', {
            describe: 'Username to authenticate with the instance (basic auth only; if omitted, prompts)',
            type: 'string',
            hidden: true,
        })
        .option('passwordStdin', {
            alias: 'password-stdin',
            describe: 'Read the password from stdin until EOF (basic auth only; if omitted, prompts)',
            type: 'boolean',
            hidden: true,
        })
        .check((args: Options) => demandOneOf(args, ['add', 'delete', 'use', 'list']))
        .check((args: Options) => demandNotEmpty(args, ['add', 'delete', 'use']))
        .check((args: Options) => {
            if ((args.username !== undefined || args.passwordStdin) && !args.add) {
                throw new Error('--username and --password-stdin can only be used with --add')
            }
            return true
        })
        .group(['add', 'type', 'alias'], 'Add:')
        .group(['delete'], 'Delete:')
        .group(['list'], 'List:')
        .group(['use'], 'Use:')
        .example([
            ['$0 auth --add foo --type basic', 'Adds basic credentials for instance foo'],
            ['$0 auth --delete bar', 'Deletes saved credentials with alias bar'],
            ['$0 auth --use bar', 'Sets credentials with alias bar as default'],
            ['$0 auth --list', 'Lists all saved credentials'],
            [
                'echo "$SN_PASSWORD" | $0 auth --add https://h --type basic --alias x --username admin --password-stdin',
                'Stores credentials fully non-interactively (pipe password into stdin)',
            ],
        ])
}

export async function handler(args: ArgumentsCamelCase<Options>): Promise<void> {
    try {
        if (args.add) {
            await interactiveAddCredentials({
                host: args.add,
                type: args.type,
                alias: args.alias,
                username: args.username,
                passwordStdin: args.passwordStdin,
            })
        } else if (args.delete) {
            await deleteCredential(args.delete)
        } else if (args.use) {
            await useCredential(args.use)
        } else if (args.list) {
            await listCredentials()
        }
        return
    } catch (error) {
        logger.error(error)
        process.exitCode = 1
    }
}

async function interactiveAddCredentials(args: AddArguments): Promise<void> {
    const authInfo = await promptAuthInfo(args)
    logger.info(`Authenticating to instance "${authInfo.host}" with ${authInfo.type} credentials.`)

    let cred: Creds | undefined

    switch (authInfo.type) {
        case 'oauth':
            cred = await oAuthLogin(authInfo.host)
            break
        case 'basic':
            cred = await basicLogin(authInfo.host, authInfo.username, authInfo.password)
            break
    }

    if (!cred) {
        logger.error(`Login to instance ${authInfo.host} failed`)
        return
    }

    const { instanceUrl } = cred
    logger.info(`Successfully authenticated to instance ${instanceUrl}.`)

    await withTelemetryEvent({ event: 'authSave', sdkDir: __dirname, instanceUrl: new URL(instanceUrl) }, async () => {
        logger.info(`Storing credentials for instance "${instanceUrl}" with alias ${authInfo.alias}.`)
        await storeCredentials(authInfo.alias, cred, true)
        logger.info(`Successfully stored credentials for instance "${instanceUrl}" with alias ${authInfo.alias}.`)
        return { authType: authInfo.type }
    })
}

async function basicLogin(host: string, username: string, password: string): Promise<Creds | undefined> {
    const sessionToken = await getUISessionToken({ instanceUrl: host, username, password })
    if (!sessionToken) {
        return
    }
    return { instanceUrl: host, type: 'basic', username, password }
}

async function oAuthLogin(host: string): Promise<Creds | undefined> {
    const tokenSet = await getOAuthTokens(host)
    if (!tokenSet) {
        return
    }
    return { instanceUrl: host, type: 'oauth', ...tokenSet }
}

async function readPasswordFromStdin(): Promise<string> {
    if (process.stdin.isTTY) {
        throw new Error('--password-stdin requires piped input; stdin is a terminal')
    }
    const chunks: Buffer[] = []
    for await (const chunk of process.stdin) {
        chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk)
    }
    let value = Buffer.concat(chunks).toString('utf8')
    if (value.endsWith('\r\n')) {
        value = value.slice(0, -2)
    } else if (value.endsWith('\n')) {
        value = value.slice(0, -1)
    }
    if (value.length === 0) {
        throw new Error('--password-stdin was passed but no password was read from stdin')
    }
    return value
}

async function promptAuthInfo(args: AddArguments): Promise<AuthInfo> {
    const type =
        args.type ||
        (await select({
            message: 'Type of authentication to use',
            default: 'basic',
            choices: [{ value: 'oauth' }, { value: 'basic' }],
        }))
    const alias =
        args.alias ||
        (await input({
            message: 'Alias for these credentials',
            // TODO (jaz): new versions of @inquirer support a `required` arg
            validate(alias: string) {
                return alias?.trim()?.length > 0
            },
        }))
    const host = args.host.startsWith('http') ? args.host : `https://${args.host}.service-now.com`

    if (type === 'oauth') {
        return { type: 'oauth', host, alias }
    }

    const username =
        args.username ||
        (await input({
            message: 'The username to authenticate with the instance',
            default: 'admin',
        }))
    const password = args.passwordStdin
        ? await readPasswordFromStdin()
        : await passwordInput({
              message: 'The password to authenticate with the instance',
              validate(val) {
                  return val.length > 0
              },
          })

    return { type: 'basic', host, alias, username, password }
}

async function deleteCredential(alias: string): Promise<void> {
    await withTelemetryEvent({ event: 'authDelete', sdkDir: __dirname }, () => removeCredentials(alias))
}

async function useCredential(alias: string): Promise<void> {
    await withTelemetryEvent({ event: 'authUse', sdkDir: __dirname }, () => updateDefaultCredential(alias))
}

async function listCredentials(): Promise<void> {
    await withTelemetryEvent({ event: 'authList', sdkDir: __dirname }, async () => {
        const storedCreds = await fetchCredentials()
        if (storedCreds.size === 0) {
            logger.info(`No credentials found`)
            return
        }

        logger.info(`Listing all credentials: `)
        storedCreds.forEach((creds, alias) => {
            prettyPrintCredentials(creds, alias)
        })
    })
}

function prettyPrintCredentials(storedCreds: CredentialPreview, alias?: string): void {
    if (alias) {
        console.log(storedCreds.isDefault ? chalk.cyan(`*[${alias}]`) : chalk.cyan(`[${alias}]`))
    }
    console.log(`      host = ${storedCreds.instanceUrl}`)
    console.log(`      type = ${storedCreds.type}`)
    if (storedCreds.type === 'basic') {
        console.log(`      username = ${storedCreds.username}`)
    }

    console.log(`      ${storedCreds.isDefault ? chalk.bold.green('default = Yes') : 'default = No'}`)
}

function demandOneOf(args: Options, demandedOptions: (keyof Options)[]): boolean {
    const count = demandedOptions.filter((option) => args[option] !== undefined).length
    const lastOption = demandedOptions.pop()
    if (count === 0) {
        throw new Error(`Exactly one of the options ${demandedOptions.join(', ')}, and ${lastOption} is required`)
    } else if (count > 1) {
        throw new Error(`Options ${demandedOptions.join(', ')}, and ${lastOption} are mutually exclusive`)
    }
    return true
}

function demandNotEmpty(args: Options, demandedOptions: (keyof Options)[]): boolean {
    for (const option of demandedOptions) {
        if (args[option] === '') {
            throw new Error(`Missing required argument for --${option}`)
        }
    }
    return true
}
